def cohen_kappa(humano, juiz):
    n = len(humano)
    po = sum(h == j for h, j in zip(humano, juiz)) / n
    pe = 0
    for classe in (0, 1):
        ph = sum(h == classe for h in humano) / n
        pj = sum(j == classe for j in juiz) / n
        pe += ph * pj
    return (po - pe) / (1 - pe) if pe != 1 else 1.0

def recall_invalidos(humano, juiz):
    invalidos = [(h, j) for h, j in zip(humano, juiz) if h == 0]
    return sum(j == 0 for _, j in invalidos) / len(invalidos)
